#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> arr1(k);
    for (int i = 0; i < k; ++i)
        cin >> arr1[i];

    int to = n * 8;

    for (int i = 0; i < k; ++i) {
        while (arr1[i] > 0) {
            if (arr1[i] % 8 == 0) {
                to -= 8;
                arr1[i] -= 8;
            } else {
                int c = arr1[i] % 4;
                if (c == 3 || c == 0) {
                    to -= 4;
                    arr1[i] -= (c == 0 ? 4 : 3);
                } else {
                    to -= 2;
                    arr1[i] -= c;
                }
            }
        }
    }

    cout << (to >= 0 ? "YES" : "NO");
    return 0;
}

