#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> arr(k);
    for (int& x : arr)
        cin >> x;

    int remaining = n * 8;

    for (int x : arr) {
        while (x > 0) {
            if (x % 8 == 0) {
                remaining -= 8;
                x -= 8;
            } else {
                int c = x % 4;

                if (c == 3 || c == 0) {
                    remaining -= 4;
                    x -= (c == 0 ? 4 : 3);
                } else {
                    remaining -= 2;
                    x -= c;
                }
            }
        }
    }

    cout << (remaining >= 0 ? "YES" : "NO");
    return 0;
}

